with days as (


    select (


    dateadd(
        day,
        row_number() over (order by 1) - 1,
        cast('2000-01-01' as date)
        )


    ) as date_day
    from table(flatten(input => array_generate_range(0, datediff(
        day,
        cast('2000-01-01' as date),
        cast('2030-01-01' as date)
        ) )))


),

final as (
    select cast(date_day as date) as date_day
    from days
)

select * from final

